SELECT kommunenummer, ST_AsGeoJSON(ST_Transform(omrade,4326)) AS omrade_geojson, ST_XMin(ST_Envelope(omrade)) AS xmin, ST_YMin(ST_Envelope(omrade)) AS ymin, ST_XMax(ST_Envelope(omrade)) AS xmax, ST_YMax(ST_Envelope(omrade)) AS ymax FROM kommuner_627ee106072240e99d2b21ec4717bf01.kommune WHERE kommunenavn ILIKE '%trondheim%';

